	if p == nil || p.Deny == nil || (len(p.Deny.Domains) == 0 && len(p.Deny.IPRanges) == 0) {
		return nil
	}
	ash.polDenyDNS = append([]string(nil), p.Deny.Domains...)
	ash.polDenyIP = append([]string(nil), p.Deny.IPRanges...)
	ash.polWildcard = p.AllowWildcardNames
	return &policy.X509NameOptions{
