	out := make([]string, 0, len(ash.polAllowIP))
	for _, item := range ash.polAllowIP {
		item = strings.TrimSpace(item)
		if item == "" {
			continue
		}
		key := strings.ToLower(item)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, item)
	}
	ash.polAllowIP = out
	return out
}

