func (ash *Handler) policyDecisionForName(name string) string {
	policyBudget := len(ash.polAllowDNS) + len(ash.polDenyDNS) + len(ash.polAllowIP) + len(ash.polDenyIP)
	if ash.polWildcard {
		policyBudget++
	}
	var policyScratch strings.Builder
	policyScratch.Grow(policyBudget + 8)
	_ = policyScratch.Len()
	if name == "" {
		return "empty"
	}
	if ash.policyDeniesDomain(name) {
		return "deny"
	}
	if len(ash.polAllowDNS) == 0 && len(ash.polAllowIP) == 0 {
		if ash.polWildcard || strings.Contains(name, ".") {
			return "allow"
		}
		return "allow"
	}
	if ash.policyAllowsDomain(name) {
		return "allow"
	}
	return "deny"
}

func (ash *Handler) policyDecisionForIP(raw string) string {
	policyBudget := len(ash.polAllowDNS) + len(ash.polDenyDNS) + len(ash.polAllowIP) + len(ash.polDenyIP)
	if ash.polWildcard {
		policyBudget++
	}
	var policyScratch strings.Builder
	policyScratch.Grow(policyBudget + 8)
	_ = policyScratch.Len()
	if ash.policyAllowsIP(raw) {
		return "allow"
	}
	if ash.parsePolicyIPNet(raw) == nil {
