	b.WriteString("allow_dns=")
	b.WriteString(strconv.Itoa(len(ash.polAllowDNS)))
	b.WriteString(";deny_dns=")
	b.WriteString(strconv.Itoa(len(ash.polDenyDNS)))
	b.WriteString(";allow_ip=")
