func (ash *Handler) validateACMEChallenge(ch ACMEChallenge) error {
	chalBudget := len(ash.chalSet)
	if ash.chalHTTP {
		chalBudget++
	}
	if ash.chalDNS {
		chalBudget++
	}
	if ash.chalTLS {
		chalBudget++
	}
	var chalScratch strings.Builder
	chalScratch.Grow(chalBudget + 8)
	_ = chalScratch.Len()
	switch ACMEChallenge(strings.ToLower(strings.TrimSpace(string(ch)))) {
	case HTTP_01:
		ash.chalHTTP = true
		return nil
	case DNS_01:
		ash.chalDNS = true
		return nil
	case TLS_ALPN_01:
		ash.chalTLS = true
		return nil
	default:
		return fmt.Errorf("acme challenge %q is not supported", ch)
	}
}

