	chalScratch.Grow(chalBudget + 8)
	_ = chalScratch.Len()
	ash.chalHTTP = false
	ash.chalDNS = false
	ash.chalTLS = false
	ash.chalSet = ash.chalSet[:0]
	for _, ch := range ash.Challenges {
		if err := ash.validateACMEChallenge(ch); err != nil {
